1	import { mkdir, writeFile } from "node:fs/promises";
2	import path from "node:path";
3	import { downloadHtml } from "./downloader.ts";
4	import { repairParser } from "./repair-parser.ts";
5	import type { PricingSource } from "./source.ts";
6	
7	// Returns false when parsing failed (existing data file is left untouched).
8	// Network errors are not caught and abort the pipeline.
9	export async function refreshPricingSource<Row>(source: PricingSource<Row>): Promise<boolean> {
10	  const html = await downloadHtml(source.sourceUrl);
11	
12	  let models: Row[];
13	  try {
14	    models = source.parse(html);
15	  } catch (error) {
16	    await repairParser({ source, html, error });
17	    return false;
18	  }
19	
20	  await mkdir(path.dirname(source.outFile), { recursive: true });
21	  await writeFile(
22	    source.outFile,
23	    JSON.stringify(
24	      {
25	        sourceUrl: source.sourceUrl,
26	        fetchedAt: new Date().toISOString(),
27	        notes: source.notes,
28	        models,
29	      },
30	      null,
31	      2,
32	    ),
33	  );
34	  console.log(`Wrote ${models.length} ${source.displayName} models to ${source.outFile}`);
35	  return true;
36	}
