1	export class NetworkError extends Error {
2	  url: string;
3	  status?: number;
4	
5	  constructor(message: string, url: string, options?: { status?: number; cause?: unknown }) {
6	    super(message, { cause: options?.cause });
7	    this.name = "NetworkError";
8	    this.url = url;
9	    this.status = options?.status;
10	  }
11	}
12	
13	export async function downloadHtml(url: string): Promise<string> {
14	  let res: Response;
15	  try {
16	    res = await fetch(url);
17	  } catch (err) {
18	    throw new NetworkError(`Request to ${url} failed: ${(err as Error).message}`, url, {
19	      cause: err,
20	    });
21	  }
22	
23	  if (!res.ok) {
24	    const body = await res.text();
25	    throw new NetworkError(`${res.status} ${res.statusText} on ${url}: ${body}`, url, {
26	      status: res.status,
27	    });
28	  }
29	  return res.text();
30	}
