1	// Combines local provider pricing + Artificial Analysis benchmark data into
2	// per-category recommendations.
3	
4	import { readFile, writeFile, mkdir } from "node:fs/promises";
5	import path from "node:path";
6	
7	export type Provider = "copilot" | "opencode-go";
8	
9	interface Candidate {
10	  provider: Provider;
11	  model: string;
12	  priceInput: number;
13	  priceOutput: number;
14	}
15	
16	export interface MappingEntry {
17	  provider: Provider;
18	  providerModel: string;
19	  aaSlug: string | null;
20	  note?: string;
21	}
22	
23	export interface AaModel {
24	  id: string;
25	  name: string;
26	  slug: string;
27	  evaluations: {
28	    artificial_analysis_intelligence_index?: number | null;
29	    artificial_analysis_coding_index?: number | null;
30	    artificial_analysis_agentic_index?: number | null;
31	  };
32	  performance?: {
33	    median_output_tokens_per_second?: number | null;
34	  };
35	}
36	
37	interface CategoryWeights {
38	  agenticIndex?: number;
39	  codingIndex?: number;
40	  intelligenceIndex?: number;
41	  costEfficiency?: number;
42	  speed?: number;
43	}
44	
45	interface BlacklistEntry {
46	  match: string;
47	  reason: string;
48	}
49	
50	interface ScoredCandidate {
51	  provider: Provider;
52	  model: string;
53	  aaSlug: string;
54	  score: number;
55	  breakdown: Record<string, number>;
56	  priceBlendedPer1M: number;
57	}
58	
59	const OUTPUT_OUTPUT_TO_INPUT_RATIO = 3; // assume 3 output tokens per 1 input token (typical agentic workload)
60	
61	function blendedPrice(priceInput: number, priceOutput: number): number {
62	  const totalParts = 1 + OUTPUT_OUTPUT_TO_INPUT_RATIO;
63	  return (priceInput * 1 + priceOutput * OUTPUT_OUTPUT_TO_INPUT_RATIO) / totalParts;
64	}
65	
66	// Strips variant qualifiers like " (<= 256K tokens)", " (Off-Peak)", " (Peak)" so
67	// tiered/peak pricing rows collapse to one representative candidate per base model.
68	export function baseModelName(model: string): string {
69	  let stripped = model;
70	  while (/\s*\([^)]*\)\s*$/.test(stripped)) {
71	    stripped = stripped.replace(/\s*\([^)]*\)\s*$/, "").trim();
72	  }
73	  return stripped;
74	}
75	
76	function dedupeCheapest(
77	  rows: { model: string; priceInput: number; priceOutput: number }[],
78	): { model: string; priceInput: number; priceOutput: number }[] {
79	  const byBase = new Map<string, { model: string; priceInput: number; priceOutput: number }>();
80	  for (const row of rows) {
81	    const base = baseModelName(row.model);
82	    const existing = byBase.get(base);
83	    if (
84	      !existing ||
85	      blendedPrice(row.priceInput, row.priceOutput) <
86	        blendedPrice(existing.priceInput, existing.priceOutput)
87	    ) {
88	      byBase.set(base, { model: base, priceInput: row.priceInput, priceOutput: row.priceOutput });
89	    }
90	  }
91	  return [...byBase.values()];
92	}
93	
94	export async function loadCandidates(): Promise<Candidate[]> {
95	  const copilotRaw = JSON.parse(
96	    await readFile(path.join("data", "copilot", "models-pricing.json"), "utf8"),
97	  );
98	  const opencodeRaw = JSON.parse(
99	    await readFile(path.join("data", "opencode-go", "models-pricing.json"), "utf8"),
100	  );
101	
102	  const copilotRows = dedupeCheapest(
103	    copilotRaw.models.map((m: { model: string; price1mInput: number; price1mOutput: number }) => ({
104	      model: m.model,
105	      priceInput: m.price1mInput,
106	      priceOutput: m.price1mOutput,
107	    })),
108	  );
109	  const opencodeRows = dedupeCheapest(
110	    opencodeRaw.models.map((m: { model: string; priceInput: number; priceOutput: number }) => ({
111	      model: m.model,
112	      priceInput: m.priceInput,
113	      priceOutput: m.priceOutput,
114	    })),
115	  );
116	
117	  return [
118	    ...copilotRows.map((r) => ({
119	      provider: "copilot" as const,
120	      model: r.model,
121	      priceInput: r.priceInput,
122	      priceOutput: r.priceOutput,
123	    })),
124	    ...opencodeRows.map((r) => ({
125	      provider: "opencode-go" as const,
126	      model: r.model,
127	      priceInput: r.priceInput,
128	      priceOutput: r.priceOutput,
129	    })),
130	  ];
131	}
132	
133	function normalize(value: number, min: number, max: number): number {
134	  if (max === min) return 1;
135	  return (value - min) / (max - min);
136	}
137	
138	export async function computeScores(): Promise<void> {
139	  const config = JSON.parse(await readFile(path.join("config", "categories.json"), "utf8"));
140	  const blacklist: BlacklistEntry[] = JSON.parse(
141	    await readFile(path.join("config", "blacklist.json"), "utf8"),
142	  );
143	  const allCandidates = await loadCandidates();
144	
145	  const candidates = allCandidates.filter((c) => {
146	    const hit = blacklist.find((b) => c.model.toLowerCase().includes(b.match.toLowerCase()));
147	    if (hit) {
148	      console.warn(`Blacklisted ${c.provider}/${c.model}: ${hit.reason}`);
149	      return false;
150	    }
151	    return true;
152	  });
153	
154	  const mapping: MappingEntry[] = JSON.parse(
155	    await readFile(path.join("config", "model-mapping.json"), "utf8"),
156	  );
157	  const aaData = JSON.parse(
158	    await readFile(path.join("data", "artificial-analysis", "language-models.json"), "utf8"),
159	  );
160	  const aaBySlug = new Map<string, AaModel>((aaData.models as AaModel[]).map((m) => [m.slug, m]));
161	
162	  const enriched: {
163	    provider: Provider;
164	    model: string;
165	    aaSlug: string;
166	    agenticIndex: number;
167	    codingIndex: number;
168	    intelligenceIndex: number;
169	    speed: number;
170	    blendedPrice1m: number;
171	  }[] = [];
172	
173	  for (const candidate of candidates) {
174	    const map = mapping.find(
175	      (m) => m.provider === candidate.provider && m.providerModel === candidate.model,
176	    );
177	    if (!map || !map.aaSlug) {
178	      console.warn(
179	        `Skipping ${candidate.provider}/${candidate.model}: no Artificial Analysis mapping.`,
180	      );
181	      continue;
182	    }
183	    const aa = aaBySlug.get(map.aaSlug);
184	    if (!aa) {
185	      console.warn(
186	        `Skipping ${candidate.provider}/${candidate.model}: aaSlug "${map.aaSlug}" not found in fetched data.`,
187	      );
188	      continue;
189	    }
190	    const {
191	      artificial_analysis_agentic_index,
192	      artificial_analysis_coding_index,
193	      artificial_analysis_intelligence_index,
194	    } = aa.evaluations;
195	    const speed = aa.performance?.median_output_tokens_per_second;
196	    if (
197	      artificial_analysis_agentic_index == null ||
198	      artificial_analysis_coding_index == null ||
199	      artificial_analysis_intelligence_index == null ||
200	      speed == null
201	    ) {
202	      console.warn(
203	        `Skipping ${candidate.provider}/${candidate.model}: incomplete benchmark data for "${map.aaSlug}".`,
204	      );
205	      continue;
206	    }
207	
208	    enriched.push({
209	      provider: candidate.provider,
210	      model: candidate.model,
211	      aaSlug: map.aaSlug,
212	      agenticIndex: artificial_analysis_agentic_index,
213	      codingIndex: artificial_analysis_coding_index,
214	      intelligenceIndex: artificial_analysis_intelligence_index,
215	      speed,
216	      blendedPrice1m: blendedPrice(candidate.priceInput, candidate.priceOutput),
217	    });
218	  }
219	
220	  const categories: Record<string, Record<Provider, ScoredCandidate[]>> = {};
221	
222	  for (const [categoryName, categoryConfig] of Object.entries(config.categories) as [
223	    string,
224	    { weights: CategoryWeights },
225	  ][]) {
226	    const weights = categoryConfig.weights;
227	    if (enriched.length === 0) {
228	      categories[categoryName] = { copilot: [], "opencode-go": [] };
229	      continue;
230	    }
231	
232	    const costEfficiencies = enriched.map((e) => 1 / e.blendedPrice1m);
233	    const ranges = {
234	      agenticIndex: [
235	        Math.min(...enriched.map((e) => e.agenticIndex)),
236	        Math.max(...enriched.map((e) => e.agenticIndex)),
237	      ],
238	      codingIndex: [
239	        Math.min(...enriched.map((e) => e.codingIndex)),
240	        Math.max(...enriched.map((e) => e.codingIndex)),
241	      ],
242	      intelligenceIndex: [
243	        Math.min(...enriched.map((e) => e.intelligenceIndex)),
244	        Math.max(...enriched.map((e) => e.intelligenceIndex)),
245	      ],
246	      speed: [Math.min(...enriched.map((e) => e.speed)), Math.max(...enriched.map((e) => e.speed))],
247	      costEfficiency: [Math.min(...costEfficiencies), Math.max(...costEfficiencies)],
248	    };
249	
250	    const scored: ScoredCandidate[] = enriched.map((e, i) => {
251	      const normAgentic = normalize(e.agenticIndex, ranges.agenticIndex[0], ranges.agenticIndex[1]);
252	      const normCoding = normalize(e.codingIndex, ranges.codingIndex[0], ranges.codingIndex[1]);
253	      const normIntelligence = normalize(
254	        e.intelligenceIndex,
255	        ranges.intelligenceIndex[0],
256	        ranges.intelligenceIndex[1],
257	      );
258	      const normSpeed = normalize(e.speed, ranges.speed[0], ranges.speed[1]);
259	      const normCost = normalize(
260	        costEfficiencies[i],
261	        ranges.costEfficiency[0],
262	        ranges.costEfficiency[1],
263	      );
264	
265	      const score =
266	        (weights.agenticIndex ?? 0) * normAgentic +
267	        (weights.codingIndex ?? 0) * normCoding +
268	        (weights.intelligenceIndex ?? 0) * normIntelligence +
269	        (weights.costEfficiency ?? 0) * normCost +
270	        (weights.speed ?? 0) * normSpeed;
271	
272	      return {
273	        provider: e.provider,
274	        model: e.model,
275	        aaSlug: e.aaSlug,
276	        score: Math.round(score * 1000) / 1000,
277	        breakdown: {
278	          agenticIndex: e.agenticIndex,
279	          codingIndex: e.codingIndex,
280	          intelligenceIndex: e.intelligenceIndex,
281	          speed: e.speed,
282	          costEfficiency: Math.round(costEfficiencies[i] * 1000) / 1000,
283	        },
284	        priceBlendedPer1M: Math.round(e.blendedPrice1m * 1000) / 1000,
285	      };
286	    });
287	
288	    scored.sort((a, b) => b.score - a.score);
289	
290	    categories[categoryName] = {
291	      copilot: scored.filter((s) => s.provider === "copilot").slice(0, config.topNPerProvider),
292	      "opencode-go": scored
293	        .filter((s) => s.provider === "opencode-go")
294	        .slice(0, config.topNPerProvider),
295	    };
296	  }
297	
298	  const outFile = path.join("data", "recommendations.json");
299	  await mkdir(path.dirname(outFile), { recursive: true });
300	  await writeFile(
301	    outFile,
302	    JSON.stringify(
303	      {
304	        generatedAt: new Date().toISOString(),
305	        topNPerProvider: config.topNPerProvider,
306	        candidatesConsidered: enriched.length,
307	        categories,
308	      },
309	      null,
310	      2,
311	    ),
312	  );
313	
314	  console.log(
315	    `Wrote recommendations for ${Object.keys(categories).length} categories (${enriched.length} scored candidates) to ${outFile}`,
316	  );
317	}
